BND_st.lat=40.05;
BND_st.lon=-88.37;
BND_st.alt=230;
BND_st.env='con';
BND_st.footp='RB';
%%

BND_rd=read_betsy_2026('C:\github_trend\raw_data\bnd_1994_2025',BND_st.name); %[output:888e29de] %[output:3fb7f93e]
%%
datevec(BND_rd.Time(1)) %[output:40a9a2ef]
datevec(BND_rd.Time(end)) %[output:2bfcfff4]
prctile(BND_rd.U0_S11,[5 50 95]) % always < 50% med=22.5% %[output:74b50700]
prctile(BND_rd.U1_S11,[5 50 95]) % always < 50% med=22.5% %[output:83b3e6fc]
%prctile(BND_rd.U_S11,[5 50 95])
% figure;
% plot(BND_rd.Time, BND_rd.U0_S11,'b.');
% hold on;
% plot(BND_rd.Time, BND_rd.U1_S11,'g.');
% plot(BND_rd.Time, BND_rd.U_S11,'r.');
plotFigControl(BND_rd, BND_st.name); %[output:99dd8493] %[output:23f98c86] %[output:584a01c3] %[output:9499488f] %[output:3d0ae9df] %[output:7c2a0f46] %[output:7ff01f76] %[output:60c26de7] %[output:826d9f3a]
% 2 size cut, ok
% sc: ok, no clear seasonal cycle, no negatives
% abs: 2 size cut, no clear seasonal cycle, few negatives
%ratio between abs wavelengths has a clear seasonal cycle with max in winter
%ratio Bs/Ba has a clear seasonality with max in winter

%%
lambdaSC=[450;550;700]*ones(1,4);
lambdaAE=[467;530;660]*ones(1,4);
BND_cal=compute_exp_SSA(BND_rd,lambdaSC, lambdaAE);
plotFigControl_cal(BND_cal, BND_st.name); %[output:04180d5e] %[output:2b27ac01] %[output:0f36af75]
